/**
 * Web layer: turns GET /api/hello into a JSON greeting. A controller only speaks HTTP,
 * so anything bigger than a greeting belongs in a service it calls.
 */
@RestController
@RequestMapping("/api/hello")
public class HelloController {

    public record Greeting(String message) {}

    // A missing or empty ?name= falls back to the default. The constraints answer 400 for the rest.
    @GetMapping
    public Greeting hello(@RequestParam(defaultValue = "World") @NotBlank @Size(max = 40) String name) {
        return new Greeting("Hello, " + name + "!");
    }
}

/**
 * A web slice test: only HelloController and Spring MVC start, with no server and no database,
 * and MockMvcTester sends requests straight to the controller.
 */
@WebMvcTest(HelloController.class)
class HelloControllerTest {

    @Autowired
    MockMvcTester mvc;

    @Test
    void greetsByName() {
        assertThat(mvc.get().uri("/api/hello").param("name", "Ana"))
                .hasStatusOk()
                .bodyJson().extractingPath("$.message").isEqualTo("Hello, Ana!");
    }

    @Test
    void greetsTheWorldWithoutAName() {
        assertThat(mvc.get().uri("/api/hello"))
                .hasStatusOk()
                .bodyJson().isEqualTo("""
                        {"message": "Hello, World!"}
                        """);
    }

    @Test
    void rejectsANameLongerThan40Characters() {
        assertThat(mvc.get().uri("/api/hello").param("name", "a".repeat(41)))
                .hasStatus(HttpStatus.BAD_REQUEST)
                .bodyJson().extractingPath("$.title").isEqualTo("Bad Request");
    }
}

@WebMvcTest(ProductController.class)
@Import(SecurityConfig.class)
class ProductControllerTest {

    private static final String NEW_PRODUCT = """
            {"sku": "KT-007", "name": "Salad Spinner", "priceCents": 2299, "stock": 12, "category": "kitchen"}
            """;

    private static final ProductResponse SALAD_SPINNER =
            new ProductResponse("KT-007", "Salad Spinner", "", 2299, 12, "kitchen", true);

    @Autowired
    MockMvcTester mvc;

    @MockitoBean
    CatalogService catalog;

    // The resource server needs a JwtDecoder to start. jwt() skips decoding, so a mock is enough.
    @MockitoBean
    JwtDecoder jwtDecoder;

    @Test
    void anyoneCanReadAProduct() {
        given(catalog.get("KT-007")).willReturn(SALAD_SPINNER);

        assertThat(mvc.get().uri("/api/products/KT-007"))
                .hasStatusOk()
                .bodyJson().extractingPath("$.name").isEqualTo("Salad Spinner");
    }

@Test
void creatingWithoutATokenAnswers401() {
    MvcTestResult result = mvc.post().uri("/api/products")
            .contentType(MediaType.APPLICATION_JSON).content(NEW_PRODUCT).exchange();

    assertThat(result).hasStatus(HttpStatus.UNAUTHORIZED);
    assertThat(result.getResponse().getHeader("WWW-Authenticate")).startsWith("Bearer");
    then(catalog).shouldHaveNoInteractions();
}

@Test
void aCustomerCannotCreateProducts() {
    assertThat(mvc.post().uri("/api/products").with(tokenWithRole("ROLE_CUSTOMER"))
            .contentType(MediaType.APPLICATION_JSON).content(NEW_PRODUCT))
            .hasStatus(HttpStatus.FORBIDDEN);
    then(catalog).shouldHaveNoInteractions();
}

@Test
void anAdminCreatesAProduct() {
    given(catalog.create(any(ProductRequest.class))).willReturn(SALAD_SPINNER);

    assertThat(mvc.post().uri("/api/products").with(tokenWithRole("ROLE_ADMIN"))
            .contentType(MediaType.APPLICATION_JSON).content(NEW_PRODUCT))
            .hasStatus(HttpStatus.CREATED)
            .hasHeader("Location", "/api/products/KT-007")
            .bodyJson().extractingPath("$.sku").isEqualTo("KT-007");
}

// ...

private static JwtRequestPostProcessor tokenWithRole(String role) {
    return jwt().authorities(new SimpleGrantedAuthority(role));
}

@Test
void invalidFieldsAnswer400WithOneErrorPerField() {
    assertThat(mvc.post().uri("/api/products").with(tokenWithRole("ROLE_ADMIN"))
            .contentType(MediaType.APPLICATION_JSON)
            .content("""
                    {"sku": "kt7", "name": " ", "priceCents": 0, "category": "kitchen"}
                    """))
            .hasStatus(HttpStatus.BAD_REQUEST)
            .bodyJson().isLenientlyEqualTo("""
                    {
                      "title": "Bad Request",
                      "errors": {
                        "name": "must not be blank",
                        "priceCents": "must be greater than 0",
                        "sku": "must look like AB-123",
                        "stock": "must not be null"
                      }
                    }
                    """);
    then(catalog).shouldHaveNoInteractions();
}

@Mock
OrderRepository orders;

@Mock
ProductRepository products;

@Mock
CustomerRepository customers;

OrderService service;

final Customer ana = new Customer("ana@example.com", "Ana Lima", "{noop}unused", Role.CUSTOMER, NOW);
final Category kitchen = new Category("Kitchen", "kitchen");
final Product knife = new Product("KT-001", "Chef's Knife", "", 7999, 20, kitchen);
final Product board = new Product("KT-005", "Bamboo Cutting Board", "", 2499, 28, kitchen);

@BeforeEach
void createService() {
    ShopProperties shop = new ShopProperties("USD", new BigDecimal("0.0825"), 5000,
            new ShopProperties.Jwt("a-test-secret-that-is-at-least-32-bytes", Duration.ofHours(1)));
    service = new OrderService(orders, products, customers, shop, Clock.fixed(NOW, ZoneOffset.UTC));
}

@Test
void placingAnOrderCopiesPricesTakesStockAndAddsTax() {
    given(customers.findByEmail("ana@example.com")).willReturn(Optional.of(ana));
    given(products.findBySkuIn(List.of("KT-001", "KT-005"))).willReturn(List.of(knife, board));
    given(orders.save(any(Order.class))).willAnswer(call -> withId(call.getArgument(0), 11L));

    OrderResponse order = service.placeOrder("ana@example.com", orderOf(line("KT-001", 1), line("KT-005", 2)));

    assertThat(order.lines()).extracting(OrderResponse.Line::unitPriceCents).containsExactly(7999L, 2499L);
    assertThat(order.subtotalCents()).isEqualTo(12_997);
    assertThat(order.taxCents()).isEqualTo(1_072);
    assertThat(order.totalCents()).isEqualTo(14_069);
    assertThat(order.currency()).isEqualTo("USD");
    assertThat(knife.getStock()).isEqualTo(19);
    assertThat(board.getStock()).isEqualTo(26);
}

